    31	let relocate db query target check =
    32	  let a = anchor db query in
    33	  ignore (put db "destination.ml" target);
    34	  ignore (put db "original.ml" "removed");
    35	  let a = current db a in
    36	  Testo.check Testo.string "destination.ml" a.source_doc.locator;
    37	  Testo.check Testo.bool true
